for name, change in DATA.items():
    path=Path(name)
    original=path.read_text(encoding='utf-8')
    digest=sha256(original.encode()).hexdigest()
    if digest==change['after']:
        continue
    if digest!=change['before']:
        raise RuntimeError('Unexpected source revision: '+name)
    updated=original
    for start,end,text in reversed(change['edits']):
        updated=updated[:start]+text+updated[end:]
    if sha256(updated.encode()).hexdigest()!=change['after']:
        raise RuntimeError('Integration checksum failed: '+name)
    path.write_text(updated,encoding='utf-8')
p=Path('bloom-ui.js')
p.write_text(p.read_text().replace('windmillsies','windmills'))
print('Hearth & Harvest integration complete.')
